using System;
using System.Linq;
using System.Collections.Generic;
using NUnit.Framework;
using SporeGobbo.Geometry;
namespace SporeGobbo.CampCandidate.Tests
{
 public sealed class Stage57Tests
 {
  static CampSession New()=>new CampSession(Stage57Layout.Create());
  [Test]public void RevisedDefinitionDeterministicAndDistinct(){var d=Stage57Layout.Create();Assert.That(d.Fingerprint(),Is.EqualTo(Stage57Layout.Create().Fingerprint()));Assert.That(d.Id,Is.EqualTo("camp.candidate.5.7.v1"));Assert.That(d.Fingerprint(),Is.Not.EqualTo(AuthoredCamp.Create().Fingerprint()));}
  [Test]public void TenBedsAreOneClusterWithVariedSmallRooms(){var d=Stage57Layout.Create();Assert.That(d.Capacity,Is.EqualTo(10));Assert.That(d.Bedrooms.Count,Is.EqualTo(4));Assert.That(d.Bedrooms.All(r=>r.Id.StartsWith("dorm.")&&r.Beds.Count>=1&&r.Beds.Count<=3));var beds=d.Bedrooms.SelectMany(r=>r.Beds).ToArray();Assert.That(beds.Max(p=>p.X)-beds.Min(p=>p.X),Is.LessThan(40));Assert.That(beds.Max(p=>p.Y)-beds.Min(p=>p.Y),Is.LessThan(30));}
  [Test]public void PublicApproachesActuallyFitThreeCells(){var s=New();var f=s.Definition.Marker("fire").Interaction;foreach(string id in new[]{"arrival.first","run.departure","bones","storage","squad","shop.reserved"})Assert.That(s.Route(f,s.Definition.Marker(id).Interaction,3).Count,Is.GreaterThan(0),id);foreach(var r in s.Definition.Bedrooms)Assert.That(s.Route(f,r.Entrance,3).Count,Is.GreaterThan(0),r.Id);}
  [Test]public void EveryDormBedConstructsAndKeepsPublicRoutes(){var s=New();for(int i=0;i<10;i++){s.AddBuddy();Assert.That(s.ConstructNext(out string why),Is.True,why);Assert.That(s.Established,Is.EqualTo(i+1));foreach(string id in new[]{"run.departure","bones","squad","shop.reserved"})Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker(id).Interaction,3).Count,Is.GreaterThan(0),id);}Assert.That(s.Residents.Select(r=>r.Slot).Distinct().Count(),Is.EqualTo(10));}
  [Test]public void DormHasTwoPublicApproachesWithoutSquadBottleneck(){var s=New();var a=new Point2(88.5,86.5);var b=new Point2(105.5,96.5);Assert.That(s.Route(a,b,3).Count,Is.GreaterThan(0));Assert.That(s.Route(s.Definition.Marker("squad").Interaction,b,3).Count,Is.GreaterThan(0));}
  [Test]public void BackingsAndResidentialOwnershipSurviveOrdinaryDigging(){var s=New();var cells=new List<DualTile>();for(int y=0;y<192;y++)for(int x=0;x<192;x++)cells.Add(new DualTile(x,y));s.DigPlayer(cells);foreach(var c in cells)if(s.Definition.Protected(c.X,c.Y)||s.Definition.Category(c.X,c.Y)==CampCell.Residential)Assert.That(s.Terrain.IsSolid(c.X,c.Y));Assert.That(s.FirstDeath,Is.False);}
  [Test]public void BonesArrivalConnectionIsOrdinaryAndGateIndependent(){var s=New();var ordinary=new List<DualTile>();for(int y=61;y<77;y++)for(int x=75;x<84;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)ordinary.Add(new DualTile(x,y));Assert.That(ordinary.Count,Is.GreaterThan(10));Assert.That(s.DigPlayer(ordinary),Is.EqualTo(ordinary.Count));Assert.That(s.Active(CampCell.FirstDeath),Is.False);}
  [Test]public void ReservationsHaveFortyPlausibleBedsWithoutGeneratingThem(){var d=Stage57Layout.Create();Assert.That(Stage57Layout.Reservations.Sum(e=>e.Capacity),Is.EqualTo(40));foreach(var e in Stage57Layout.Reservations.Where(e=>e.Capacity>0)){int earth=0;for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(e.Contains(x,y)&&d.Category(x,y)==CampCell.Expansion)earth++;Assert.That(earth,Is.GreaterThan(e.Capacity*18),e.Id);}Assert.That(d.Capacity,Is.EqualTo(10));}
  [TestCase(0)][TestCase(1)]public void BothShopOptionsAreReachableBeforeDistantPit(int option){var s=new CampSession(Stage57Layout.Create(option));Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("shop.reserved").Interaction,3).Count,Is.GreaterThan(0));Assert.That(s.Route(s.Definition.Marker("fire").Interaction,s.Definition.Marker("fight.reserved").Interaction,3).Count,Is.Zero);s.FakeReturn(2,5,2);s.ConstructNext(out _);s.ConstructNext(out _);s.BuddyDied();s.Advance();Assert.That(s.ShopInspected&&!s.FightInspected);s.Advance();Assert.That(s.FightInspected);Assert.That(s.Route(s.Definition.Marker("shop.reserved").Interaction,s.Definition.Marker("fight.reserved").Interaction,3).Count,Is.GreaterThan(0));}
  [Test]public void AcceleratedClockUsesBoundedValidatedConstructionAndVacancyReuse(){var s=New();var clock=new CampConstructionPreview(s){BuildDorm=true};int frames=0;while((s.Established<10||s.Construction!=null)&&frames++<20000){clock.Tick(1.0/60);Assert.That(clock.LastTicks,Is.LessThanOrEqualTo(8));Assert.That(clock.LastBatches,Is.LessThanOrEqualTo(1));}Assert.That(s.Established,Is.EqualTo(10),clock.Status);s.BuddyDied();s.AddBuddy();Assert.That(s.Residents.Last().Slot,Is.EqualTo(1));foreach(var m in s.Definition.Markers.Where(m=>m.Id!="arrival.first"))Assert.That(s.Definition.Protected((int)m.Anchor.X,(int)m.Anchor.Y));}
  [Test]public void FinishCurrentDoesNotBuildAdditionalBedsOrTeleportThroughWalls(){var s=New();s.AddBuddy();Assert.That(s.BeginConstruction(out _));var c=new CampConstructionPreview(s){FinishCurrent=true};for(int i=0;i<10000&&s.Construction!=null;i++){c.Tick(1.0/60);Assert.That(s.Fits(s.Residents[0].Position,3));}Assert.That(s.Established,Is.EqualTo(1));Assert.That(c.BuildDorm,Is.False);}
  [Test]public void NormalClockPreservesOrdinaryTimingAndFiveBedTargetStops(){var a=New();var b=New();a.AddBuddy();b.AddBuddy();a.BeginConstruction(out _);b.BeginConstruction(out _);var c=new CampConstructionPreview(b);for(int i=0;i<240;i++){a.TickConstruction(1.0/60);c.Tick(1.0/60);}Assert.That(a.Revision,Is.EqualTo(b.Revision));Assert.That(a.Residents[0].Position,Is.EqualTo(b.Residents[0].Position));var five=New();var clock=new CampConstructionPreview(five){BuildDorm=true,BuildTarget=5};for(int i=0;i<20000&&clock.BuildDorm;i++)clock.Tick(1.0/60);Assert.That(five.Established,Is.EqualTo(5));Assert.That(five.Construction,Is.Null);}
  [Test]public void FutureRingLoopsAndEntrancesHaveThreeCellClearanceAfterOrdinaryExpansion(){var s=New();var cells=new List<DualTile>();for(int y=0;y<192;y++)for(int x=0;x<192;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)cells.Add(new DualTile(x,y));s.DigPlayer(cells);s.FakeReturn(2,5,2);s.ConstructNext(out _);s.ConstructNext(out _);s.BuddyDied();s.Advance();s.Advance();var f=s.Definition.Marker("fire").Interaction;foreach(var e in Stage57Layout.Reservations.Where(e=>e.Capacity>0)){Assert.That(s.Route(f,e.Entrance,3).Count,Is.GreaterThan(0),e.Id);for(int i=0;i<16;i++){double t=i*Math.PI/8;var p=new Point2(Math.Floor(e.Center.X+e.RadiusX*.55*Math.Cos(t))+.5,Math.Floor(e.Center.Y+e.RadiusY*.55*Math.Sin(t))+.5);Assert.That(s.Fits(p,3),Is.True,e.Id);Assert.That(s.Route(e.Entrance,p,3).Count,Is.GreaterThan(0),e.Id);}}}

 }
}
